// Bangla strings — Banglish register (a deliberate choice): technical
// / product terms stay transliterated into Bangla script rather than
// translated to a pure-Bangla equivalent, matching how these terms are
// actually spoken in BD tech/business contexts. Examples: "Danger Zone" ->
// "ডেঞ্জার জোন" not "স্পর্শকাতর সেটিংস"; "Base Currency" -> "বেইজ কারেন্সি"
// not "প্রধান মুদ্রা"; "Floating ... Switcher" -> "ফ্লোটিং ... সুইচার" not a
// literal Bangla description. Everyday verbs/connectors ("করুন", "থেকে",
// "এবং") stay natural Bangla — only the technical noun itself transliterates.
// Apply this same rule to any new key added here.
//
// MUST have exactly the same keys as en.ts — the
// `satisfies Record<TranslationKey, string>` below is what enforces that;
// a missing or extra key here is a compile error, not a silent runtime gap.

