  "selfhostMove.intro": "ওপেন সোর্স Passive Coder CMS দিয়ে এই সাইট নিজের সার্ভারে চালান। সাইটের সবকিছু নিয়ে আমরা একটি সাইট প্যাকেজ বানিয়ে দেব, আপনি এক কমান্ডে সেটা লোড করবেন।",
